import React, { useState } from 'react';

const mockTracks = [
  { id: 1, name: 'Track 1', bpm: 120, genre: 'House' },
  { id: 2, name: 'Track 2', bpm: 125, genre: 'Techno' },
  { id: 3, name: 'Track 3', bpm: 118, genre: 'Trance' },
  // Add more mock tracks if needed
];

const TrackSearch = ({ onTrackSelected }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredTracks, setFilteredTracks] = useState([]);

  const handleSearch = () => {
    // Mock search by filtering mockTracks based on search term
    const results = mockTracks.filter((track) =>
      track.name.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredTracks(results);
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search for a track..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      <div>
        {filteredTracks.length > 0 ? (
          <ul>
            {filteredTracks.map((track) => (
              <li key={track.id} onClick={() => onTrackSelected(track)}>
                {track.name} - {track.genre} ({track.bpm} BPM)
              </li>
            ))}
          </ul>
        ) : (
          <p>No results found</p>
        )}
      </div>
    </div>
  );
};

export default TrackSearch;
